-- Migration 037 (formerly 018): Audit round 3 — closes the remaining gaps found in requirements 173-244, 248-283, 315-356.
-- Typed component schemas, component presets, hero library, installment providers, saved carts,
-- media pipeline runs, richer card templates, CMS-built About/Vibe pages (gallery, video, collections).

-- 1. Registry: new registered components (Req 175, 205, 274) + blog is out of scope (284-314) → disabled, never rendered empty.
ALTER TABLE cms_components DROP CONSTRAINT IF EXISTS cms_components_component_type_check;
ALTER TABLE cms_components ADD CONSTRAINT cms_components_component_type_check CHECK (component_type IN (
  'hero', 'video_hero', 'image_hero', 'banner', 'promotion_banner', 'countdown', 'product_slider', 'product_grid', 'product_carousel',
  'product_card', 'category_section', 'category_card', 'promotional', 'text_image', 'text_section', 'cta', 'installment_card',
  'brand_section', 'brand_strip', 'review_section', 'recommendation_section', 'newsletter', 'faq', 'blog_section', 'lead_form',
  'story_hero', 'brand_story', 'timeline', 'values_grid', 'gallery', 'video_section', 'stats_strip', 'spacer', 'divider',
  'collection_showcase', 'composable', 'custom'));

INSERT INTO cms_components(id, code, title, component_type, kind, field_schema, presets, variants, data_source) VALUES
  (gen_random_uuid(), 'gallery', 'گالری تصاویر', 'gallery', 'code', '{}'::jsonb, '["Grid","Masonry","Carousel"]'::jsonb, '["default","editorial","framed"]'::jsonb, 'manual'),
  (gen_random_uuid(), 'video_section', 'بخش ویدیو', 'video_section', 'code', '{}'::jsonb, '["Cinematic","Portrait","Inline"]'::jsonb, '["default","cinematic","framed"]'::jsonb, 'manual'),
  (gen_random_uuid(), 'collection_showcase', 'نمایش کالکشن‌ها', 'collection_showcase', 'code', '{}'::jsonb, '["Editorial Tiles","Minimal List"]'::jsonb, '["default","minimal","overlay"]'::jsonb, 'products')
ON CONFLICT (code) DO NOTHING;
UPDATE cms_components SET active = false, updated_at = now() WHERE code = 'blog_section';
UPDATE cms_components SET variants = '["static","video","split","editorial","product","collection","minimal","fullviewport","horizontal","cinematic","carousel","mosaic"]'::jsonb
  WHERE code IN ('hero', 'image_hero', 'video_hero');
UPDATE cms_components SET variants = '["default","editorial","compact","luxury","sale","new","premium","wholesale"]'::jsonb WHERE code IN ('product_grid', 'product_carousel', 'product_slider', 'recommendation_section');
UPDATE cms_components SET variants = '["default","snapppay","digipay","generic"]'::jsonb WHERE code = 'installment_card';
UPDATE cms_components SET variants = '["default","dark","minimal","split"]'::jsonb WHERE code IN ('newsletter', 'lead_form');
UPDATE cms_components SET variants = '["default","rating_summary","customer_photos","product_rating"]'::jsonb WHERE code = 'review_section';

