-- 3. Component presets (Req 180, 213): one click applies variant + presentational payload + style overrides.
CREATE TABLE IF NOT EXISTS cms_component_presets (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  component_code text NOT NULL,
  code text NOT NULL,
  title text NOT NULL,
  variant text NOT NULL DEFAULT 'default',
  payload jsonb NOT NULL DEFAULT '{}'::jsonb,
  style_overrides jsonb NOT NULL DEFAULT '{}'::jsonb,
  responsive_config jsonb NOT NULL DEFAULT '{}'::jsonb,
  position integer NOT NULL DEFAULT 0,
  is_system boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (component_code, code)
);
ALTER TABLE cms_component_presets DROP CONSTRAINT IF EXISTS cms_component_presets_component_code_fkey;
ALTER TABLE cms_component_presets ADD CONSTRAINT cms_component_presets_component_code_fkey
  FOREIGN KEY (component_code) REFERENCES cms_components(code) ON UPDATE CASCADE ON DELETE CASCADE;

