-- 4. Product-card templates: full designer customization + real quality-gate inputs (Req 196-198).
UPDATE cms_product_card_templates SET styles = jsonb_build_object('titleLines', 2, 'hoverEffect', 'zoom', 'ctaStyle', 'solid', 'focusRing', 'accent', 'skeleton', true, 'textAlign', 'start', 'imageFit', 'cover') || styles
  WHERE NOT (styles ? 'titleLines');
UPDATE cms_product_card_templates SET styles = styles || '{"hoverEffect":"lift","ctaStyle":"outline","badgeText":"Premium","titleLines":2}'::jsonb WHERE code = 'kolbe-premium';
UPDATE cms_product_card_templates SET styles = styles || '{"hoverEffect":"none","ctaStyle":"ghost"}'::jsonb WHERE code = 'kolbe-minimal';
UPDATE cms_product_card_templates SET styles = styles || '{"badgeText":"تازه‌رسیده"}'::jsonb WHERE code = 'kolbe-new-arrival';
UPDATE cms_product_card_templates SET styles = styles || '{"badgeText":"فروش فوری"}'::jsonb WHERE code = 'kolbe-flash-sale';

-- 5. Installment providers from the Integration/Pricing domain (Req 188-191): count, limits, logo text, terms.
CREATE TABLE IF NOT EXISTS installment_providers (
  code text PRIMARY KEY CHECK (code ~ '^[a-z0-9-]{2,30}$'),
  title text NOT NULL,
  integration_code text,
  installments_count integer NOT NULL DEFAULT 4 CHECK (installments_count BETWEEN 2 AND 24),
  min_order_rial bigint NOT NULL DEFAULT 0 CHECK (min_order_rial >= 0),
  max_order_rial bigint CHECK (max_order_rial IS NULL OR max_order_rial > 0),
  fee_percent numeric(5,2) NOT NULL DEFAULT 0 CHECK (fee_percent >= 0 AND fee_percent <= 30),
  badge_text text NOT NULL DEFAULT '',
  terms text NOT NULL DEFAULT '',
  brand_color text NOT NULL DEFAULT '#1B2A4A' CHECK (brand_color ~ '^#[0-9a-fA-F]{3,8}$'),
  logo_url text,
  position integer NOT NULL DEFAULT 0,
  active boolean NOT NULL DEFAULT true,
  updated_by uuid REFERENCES users(id),
  updated_at timestamptz NOT NULL DEFAULT now()
);
-- Providers ship INACTIVE: offers appear only after an admin enables a provider backed by a real payment contract.
INSERT INTO installment_providers(code, title, integration_code, installments_count, min_order_rial, max_order_rial, badge_text, terms, brand_color, position, active) VALUES
