  ('digipay', 'دیجی‌پی', 'digipay', 4, 10000000, 1500000000, 'اقساط دیجی‌پی', 'پرداخت در چهار قسط با اعتبارسنجی آنی دیجی‌پی.', '#2E62F5', 2, false)
ON CONFLICT (code) DO NOTHING;
INSERT INTO permissions(code, title) VALUES ('installments:manage', 'مدیریت تأمین‌کنندگان خرید اقساطی (تعداد قسط، سقف و شرایط)') ON CONFLICT (code) DO NOTHING;
INSERT INTO role_permissions(role_code, permission_code) VALUES ('admin', 'installments:manage') ON CONFLICT DO NOTHING;

-- 6. Saved cart (Req 343 «سبد ذخیره‌شده»): server copy of the customer cart; prices always re-read from Pricing.
CREATE TABLE IF NOT EXISTS saved_carts (
  user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  items jsonb NOT NULL DEFAULT '[]'::jsonb,
  updated_at timestamptz NOT NULL DEFAULT now()
);

-- 7. Automation media pipeline (Req 317): every upload gets a traceable run with per-step status.
CREATE TABLE IF NOT EXISTS media_pipeline_runs (
  id uuid PRIMARY KEY,
  subject_type text NOT NULL CHECK (subject_type IN ('product_media', 'cms_asset', 'review_photo')),
  subject_id uuid NOT NULL,
  file_id uuid REFERENCES files(id) ON DELETE SET NULL,
  status text NOT NULL DEFAULT 'queued' CHECK (status IN ('queued', 'running', 'completed', 'partial', 'failed')),
  steps jsonb NOT NULL DEFAULT '[]'::jsonb,
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  finished_at timestamptz
);
CREATE INDEX IF NOT EXISTS media_pipeline_runs_subject_idx ON media_pipeline_runs(subject_type, subject_id, created_at DESC);
ALTER TABLE customer_reviews ADD COLUMN IF NOT EXISTS photo_file_ids uuid[] NOT NULL DEFAULT '{}';

-- 8. Categories: card customization (Req 200). Vibes already have palette/cover/position (Req 202).
ALTER TABLE cms_categories ALTER COLUMN card_style SET DEFAULT '{}'::jsonb;

-- 9. Global layout: per-menu mega menus with media/collection/vibe/campaign, mobile navigation, header announcement toggle (Req 275-278).
UPDATE site_settings SET value = value
    || jsonb_build_object('showAnnouncement', COALESCE(value->'showAnnouncement', 'true'::jsonb))
    || jsonb_build_object('mobileNav', COALESCE(value->'mobileNav', '{"showCategories":true,"showVibes":true,"items":[{"label":"فروشگاه","target":"shop"},{"label":"باشگاه VIP","target":"vip"},{"label":"درباره ما","target":"about"}]}'::jsonb))
    || jsonb_build_object('megaMenu', COALESCE((SELECT jsonb_agg(col || jsonb_build_object('menuId', COALESCE(col->>'menuId', 'shop'))) FROM jsonb_array_elements(value->'megaMenu') col), '[]'::jsonb))
  WHERE key = 'global_header';

-- 10. (moved) Extra About/Vibe blocks are part of the on-demand starter content in backend/src/cms-starter.ts.

-- Normalise legacy payload aliases so every stored section passes its typed schema (Req 175-176).
UPDATE cms_sections s SET payload = (s.payload - 'text' - 'ctaLabel' - 'ctaTarget')
    || jsonb_build_object('title', COALESCE(s.payload->>'title', s.payload->>'text'))
    || CASE WHEN s.payload ? 'ctaLabel' THEN jsonb_build_object('cta', s.payload->>'ctaLabel') ELSE '{}'::jsonb END
    || CASE WHEN s.payload ? 'ctaTarget' THEN jsonb_build_object('target', s.payload->>'ctaTarget') ELSE '{}'::jsonb END
  FROM cms_components c WHERE c.id = s.component_id AND c.code = 'cta' AND s.payload ? 'text' AND NOT s.payload ? 'title';
UPDATE cms_components SET field_schema = jsonb_set(field_schema, '{fields}', (
    SELECT jsonb_agg(CASE WHEN f->>'key' = 'tone' THEN jsonb_set(f, '{options}', '["surface","navy","terra","stone"]'::jsonb) ELSE f END ORDER BY ord)
    FROM jsonb_array_elements(field_schema->'fields') WITH ORDINALITY AS t(f, ord)))
  WHERE code = 'newsletter';
